<template>
  <q-dialog :model-value="modelValue" persistent @update:model-value="$emit('update:modelValue', $event)">
    <q-card style="min-width: 300px">
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>
      <q-card-section class="row items-center">
        <span class="full-width" style="text-align: center">{{ message }}</span>
      </q-card-section>
      <q-card-actions align="right">
        <f-btn
          v-if="btnCancel"
          appearance="cancel"
          :label="cancelLabel"
          v-close-popup
        />
        <f-btn
          :appearance="confirmAppearance"
          :color="confirmColor"
          :label="confirmLabel"
          v-close-popup
          @click="$emit('confirm')"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

export default defineComponent({
  name: 'ConfirmDialog',
  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    confirmLabel: {
      type: String,
      default: 'Confirm',
    },
    cancelLabel: {
      type: String,
      default: 'Cancel',
    },
    message: {
      type: String,
      default: 'Are you sure?',
    },
    btnCancel: {
      type: Boolean,
      default: true,
    },
    confirmAppearance: {
      type: String,
      default: 'positive'
    },
    confirmColor: {
      type: String,
      default: ''
    }
  },
  emits: ['confirm', 'update:modelValue'],
});
</script>
